/**
 * Whether THIRD-PARTY-LICENSES.txt still describes this tree (TASK-26).
 *
 * The notice is generated by scripts/generate-third-party-licenses.mjs and committed, because
 * tauri.conf.json bundles it. A dependency bump without a re-run would ship a notice describing
 * the previous tree, and nothing in a diff shows that. Re-running the generator here is not
 * possible (it needs a cargo registry cache for both release targets), so the generator records a
 * digest of each in-repo input in the file's header and this compares them with the inputs now.
 *
 * Files come through `import.meta.glob` with `?raw`, which hands back the bytes on disk; that the
 * digests match at all is what shows the read is unaltered.
 */

import { describe, expect, it } from "vitest";

const OUTPUT_KEY = "../../THIRD-PARTY-LICENSES.txt";
const NOTICES_KEY = "../../THIRD-PARTY-NOTICES.md";

// The generator's input set, spelled again here; the second test fails when the two disagree.
const FILES: Record<string, string> = import.meta.glob(
  [
    "../../THIRD-PARTY-LICENSES.txt",
    "../../scripts/generate-third-party-licenses.mjs",
    "../../pnpm-lock.yaml",
    "../../src-tauri/Cargo.lock",
    "../../THIRD-PARTY-NOTICES.md",
    "../../scripts/spdx/*.txt",
  ],
  { eager: true, query: "?raw", import: "default" },
);

const GENERATED = FILES[OUTPUT_KEY];

const pathOf = (key: string) => key.replace("../../", "");
const keyOf = (path: string) => `../../${path}`;

async function sha256(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

const normalize = (text: string) => text.replace(/^﻿/, "").replace(/\r\n/g, "\n").replace(/\s+$/, "");

// Empty is an error: a parser matching nothing would let the staleness test compare two empty
// lists and pass.
function recordedInputs(): Map<string, string> {
  const recorded = new Map<string, string>();
  for (const line of GENERATED.split("\n")) {
    if (line.startsWith("SECTION 1")) {
      break;
    }
    const match = line.match(/^ {2}(\S+) +sha256 ([0-9a-f]{64})$/);
    if (match) {
      recorded.set(match[1], match[2]);
    }
  }
  if (recorded.size === 0) {
    throw new Error("THIRD-PARTY-LICENSES.txt records no input digests in its header.");
  }
  return recorded;
}

describe("THIRD-PARTY-LICENSES.txt", () => {
  it("holds its inputs and itself as LF, which keeps the digests reproducible", () => {
    const converted = Object.entries(FILES)
      .filter(([, text]) => text.includes("\r"))
      .map(([key]) => pathOf(key));

    expect(converted, "checked out with CRLF; .gitattributes pins these to LF").toEqual([]);
  });

  it("records a digest for every input this test reads, and no other", () => {
    const expected = Object.keys(FILES)
      .filter((key) => key !== OUTPUT_KEY)
      .map(pathOf)
      .sort();

    expect([...recordedInputs().keys()].sort()).toEqual(expected);
  });

  it("was generated from the inputs as they are now", async () => {
    const stale: string[] = [];
    for (const [path, digest] of recordedInputs()) {
      if ((await sha256(FILES[keyOf(path)])) !== digest) {
        stale.push(path);
      }
    }

    expect(
      stale,
      "THIRD-PARTY-LICENSES.txt is stale. Regenerate it with the commands at the top of " +
        "scripts/generate-third-party-licenses.mjs and commit the result.",
    ).toEqual([]);
  });

  it("reproduces THIRD-PARTY-NOTICES.md in full as its first section", () => {
    const body = GENERATED.split(/^SECTION 2 — NPM PACKAGES /m)[0];
    const section = body.split(/^SECTION 1 — .*\n=+\n/m)[1];

    expect(section).toBeTypeOf("string");
    expect(normalize(section)).toContain(normalize(FILES[NOTICES_KEY]));
  });
});
